input.command:
node -e '
const p = JSON.parse(require("fs").readFileSync("src/examples/quake-magnitude-viz/noodles.json","utf8"));
const ids = new Set(p.nodes.map(n=>n.id));
let ok=true;
for (const e of p.edges){
  if(!ids.has(e.source)){console.log("MISSING source",e.source);ok=false}
  if(!ids.has(e.target)){console.log("MISSING target",e.target);ok=false}
  if(e.id !== `${e.source}.${e.sourceHandle}->${e.target}.${e.targetHandle}`){console.log("ID mismatch",e.id);ok=false}
}
console.log("nodes:",p.nodes.length,"edges:",p.edges.length,"types:",[...new Set(p.nodes.map(n=>n.type))].join(","));
console.log(ok?"GRAPH CONSISTENT":"GRAPH HAS ISSUES");
'
